// MosaicFileEffects.kt -- the half of Mosaic's file effects that is the same on
// every platform Compose runs on (UI87 §7, UI89 §3.8): the rules a request
// must meet, the MIME table, the router that sends each effect to the app or
// to this library, and the asynchronous path from a picker's answer to the
// effect's outcome.
//
// Generated by mosaic-app-bindings; do not edit in a generated project. It
// imports nothing from AWT or Android, so the desktop project and the Android
// project compile the same file, each beside its own MosaicPlatformEffects.kt
// (the desktop's AWT dialogs; Android's document picker).
//
// What it answers
// ---------------
//
//   files.open  { accept: [MIME...] }
//               -> ok { name, mimeType, bytes (base64) } | cancelled {} | failed { message }
//   files.save  { suggestedName, accept: [MIME...], bytes (base64) }
//               -> ok { name } | cancelled {} | failed { message }
//
// These are UI59's and UI87's contracts. A name is returned, never a path: a
// path would tell the app (and anything it logs) where the person keeps files.
//
// Routing
// -------
//
// The app's own handler is installed first, then the router, which wraps it.
// Each effect is routed by kind:
//
//   kind the app claims ........ the app's handler
//   files.open / files.save .... this library
//   anything else .............. the app's handler if it claimed nothing
//                                (the original meaning), otherwise nobody --
//                                and the host fails an unanswered Await
//                                rather than leaving it pending.
//
// From request to outcome
// -----------------------
//
//   router: defer the effect, then on the UI thread
//     check the request ............ a refusal answers here; no picker shown
//     picker.open / picker.create
//          |   now (a desktop dialog) or later (a phone's picker), once
//          v
//     done(document)  or  done(null) ... null answers cancelled {}
//          |
//     on runInBackground: read (bounded) or write
//          v
//     the effect's outcome, completed exactly once
//
// The host's monitor is held while a handler runs, so nothing is shown from
// inside it: each standard effect is DEFERRED first. Once deferred, an effect
// is out of the host's fail sweep, so every path above -- a picker that
// throws, answers twice or never gets to answer -- ends in exactly one
// completion; a lost one would leave it awaited for the life of the process.

import java.io.ByteArrayOutputStream
import java.io.InputStream
import java.util.Base64
import java.util.concurrent.atomic.AtomicBoolean

/** The effect kinds this library answers unless an app claims them. */
val MOSAIC_STANDARD_EFFECT_KINDS: Set<String> = setOf("files.open", "files.save")

/** The largest file `files.open` reads (UI59 parity with Qt and XAML). */
const val MOSAIC_MAX_OPEN_BYTES: Long = 50L * 1024 * 1024

/** The largest payload `files.save` writes (UI87 §3.1). */
const val MOSAIC_MAX_SAVE_BYTES: Int = 16 * 1024 * 1024

// The MIME types an app names, and the extensions a dialog filters on. A type
// this table does not know is dropped rather than failing the request (UI59 §3).
internal val MOSAIC_MIME_EXTENSIONS: Map<String, List<String>> = mapOf(
    "application/json" to listOf("json"),
    "text/plain" to listOf("txt"),
    "text/markdown" to listOf("md", "markdown"),
    "text/csv" to listOf("csv"),
    "application/pdf" to listOf("pdf"),
    "application/zip" to listOf("zip"),
    "image/jpeg" to listOf("jpg", "jpeg"),
    "image/png" to listOf("png"),
    "image/webp" to listOf("webp"),
    "image/gif" to listOf("gif"),
    "image/bmp" to listOf("bmp"),
    "image/tiff" to listOf("tif", "tiff"),
    "image/svg+xml" to listOf("svg"),
)

/**
 * Whether every extension the open dialog filters on is an image's, so it can
 * start in the Pictures folder (UI59 §2: a caller that wants "pictures only"
 * accepts image types, and the dialog's start location follows). No filter at
 * all is not "only images": it means any file, and the dialog starts where it
 * always has. The same rule as the XAML and Qt libraries.
 *
 *     accept                         extensions        start
 *     ["image/png", "image/jpeg"]    png jpg jpeg      Pictures
 *     ["image/png", "text/plain"]    png txt           the dialog's default
 *     []                             (none)            the dialog's default
 */
fun mosaicOnlyImages(extensions: List<String>): Boolean =
    extensions.isNotEmpty() &&
        extensions.all { extension ->
            MOSAIC_MIME_EXTENSIONS.any { (mime, known) -> mime.startsWith("image/") && extension in known }
        }

/** The MIME type a file name suggests, from the table above. */
internal fun mosaicMimeTypeForName(name: String): String {
    val extension = name.substringAfterLast('.', "").lowercase()
    return MOSAIC_MIME_EXTENSIONS.entries.firstOrNull { extension in it.value }?.key
        ?: "application/octet-stream"
}

@Suppress("UNCHECKED_CAST")
internal fun mosaicPayloadMap(payload: Any?): Map<String, Any?> =
    payload as? Map<String, Any?> ?: emptyMap()

/**
 * What a request accepts, as a picker needs it: the MIME types this library
 * knows (Android's picker filters on these) and their extensions (a desktop
 * dialog filters on those). A type the table does not know is dropped rather
 * than failing the request (UI59 §3).
 */
class MosaicAccept(val mimeTypes: List<String>, val extensions: List<String>)

internal fun mosaicAcceptFor(payload: Map<String, Any?>): MosaicAccept {
    val known = (payload["accept"] as? List<*>).orEmpty()
        .mapNotNull { it as? String }
        .filter { it in MOSAIC_MIME_EXTENSIONS }
        .distinct()
    return MosaicAccept(known, known.flatMap { MOSAIC_MIME_EXTENSIONS.getValue(it) }.distinct())
}

internal fun mosaicOk(value: Map<String, Any?>): Map<String, Any?> = mapOf("ok" to value)
internal fun mosaicCancelled(): Map<String, Any?> = mapOf("cancelled" to emptyMap<String, Any?>())
internal fun mosaicFailed(message: String): Map<String, Any?> =
    mapOf("failed" to mapOf("message" to message))

/**
 * Read at most `limit` bytes, or null if the stream is longer. Bounded while
 * reading, not by checking the length first: a file can grow between a check
 * and a read, which is the TOCTOU the XAML handler's review found (#15218),
 * and a document provider's reported size is not to be trusted at all.
 */
fun mosaicReadBounded(stream: InputStream, limit: Long): ByteArray? {
    val out = ByteArrayOutputStream()
    val buffer = ByteArray(64 * 1024)
    // A stream may return 0 now and then; one that does nothing else would
    // hold the one file operation open for ever.
    var idle = 0
    while (true) {
        val got = stream.read(buffer)
        if (got < 0) return out.toByteArray()
        if (got == 0) {
            if (++idle > MOSAIC_MAX_IDLE_READS) throw MosaicFileFailure("couldn't read the selected file")
            continue
        }
        idle = 0
        if (out.size() + got > limit) return null
        out.write(buffer, 0, got)
    }
}

/** Reads in a row that may return nothing before a read gives up. */
private const val MOSAIC_MAX_IDLE_READS = 1000

/**
 * A suggested name is a plain file name (UI87 §3.1), so an app cannot steer the
 * dialog, or disguise what it is saving:
 *
 * - no directory separators, and not `.` or `..` -- no other directory;
 * - no leading `.` -- a hidden dot-file such as `.zshrc` is configuration a
 *   shell or tool runs, not a document;
 * - no `:` -- on Windows `D:x` names another drive, and `x:y` an alternate
 *   data stream;
 * - no control, format, line- or paragraph-separator characters -- a
 *   right-to-left override can make `invoice<RLO>fdp.exe` read as a PDF in the
 *   dialog, and a separator breaks the name across lines;
 * - no leading or trailing whitespace of any kind (a no-break space included),
 *   no run of two or more whitespace characters, and no trailing dot, which
 *   Windows silently strips -- `report.pdf` padded out and ending `.command`
 *   hides its real extension;
 * - at most 255 UTF-16 units.
 *
 * - no lone surrogate, unassigned or private-use code point;
 * - blank-rendering characters (Hangul fillers, BRAILLE PATTERN BLANK) count as
 *   whitespace, and invisible (default-ignorable) characters are dropped
 *   before the padding and dot rules.
 *
 * Checked by code point, so a format character outside the BMP (the tag
 * characters, U+E0000..) is caught as well as one inside it.
 */
fun mosaicIsPlainFileName(name: String): Boolean {
    if (name.isEmpty() || name.length > 255 || name == "." || name == "..") return false
    val refused = name.codePoints().anyMatch { point ->
        point == '/'.code || point == '\\'.code || point == ':'.code ||
            when (Character.getType(point).toByte()) {
                Character.CONTROL, Character.FORMAT,
                Character.LINE_SEPARATOR, Character.PARAGRAPH_SEPARATOR,
                // A lone surrogate cannot be written as a file name (Java
                // saves it as `?`), and unassigned or private-use code points
                // mean different things to different runtimes' Unicode tables.
                Character.SURROGATE, Character.UNASSIGNED, Character.PRIVATE_USE -> true
                else -> false
            }
    }
    if (refused) return false
    // The padding and dot rules look at what is visible: invisible characters
    // cannot split a run of spaces or hide a leading or trailing dot.
    val visible = name.codePoints().filter { !mosaicIsInvisible(it) }.toArray()
    if (visible.isEmpty()) return false
    if (visible.first() == '.'.code || visible.last() == '.'.code) return false
    if (mosaicIsSpace(visible.first()) || mosaicIsSpace(visible.last())) return false
    for (index in 1 until visible.size) {
        if (mosaicIsSpace(visible[index - 1]) && mosaicIsSpace(visible[index])) return false
    }
    return !mosaicIsReservedDeviceName(name)
}

/**
 * Windows device names: `CON`, `NUL.txt` or `com1.json` is the console,
 * the null device or a serial port there, never a file. Refused on every
 * host, so a name saves the same everywhere. Compared on the part before
 * the first dot, trailing spaces removed, ASCII letters folded to upper case (only those: a host's own upper-casing differs on `ı`).
 */
val MOSAIC_RESERVED_DEVICE_NAMES: Set<String> = setOf(
    "CON", "PRN", "AUX", "NUL", "CONIN\$", "CONOUT\$", "COM0", "COM1",
    "COM2", "COM3", "COM4", "COM5", "COM6", "COM7", "COM8", "COM9",
    "COM¹", "COM²", "COM³", "LPT0", "LPT1", "LPT2", "LPT3", "LPT4",
    "LPT5", "LPT6", "LPT7", "LPT8", "LPT9", "LPT¹", "LPT²", "LPT³",
)

/** True when [name] is a Windows device name (see [MOSAIC_RESERVED_DEVICE_NAMES]). */
fun mosaicIsReservedDeviceName(name: String): Boolean {
    // ASCII letters only: every host's own upper-casing differs on some
    // character (.NET's leaves `ı` alone, the others make it `I`).
    val stem = name.substringBefore('.').trimEnd(' ')
        .map { if (it in 'a'..'z') it - ('a' - 'A') else it }
        .joinToString("")
    return stem in MOSAIC_RESERVED_DEVICE_NAMES
}

private fun mosaicIsSpace(point: Int): Boolean =
    Character.isWhitespace(point) || Character.isSpaceChar(point) || point in MOSAIC_BLANK_CHARACTERS

/**
 * Characters that are not whitespace to Unicode but render as a wide blank,
 * so they pad a name just as well: the Hangul fillers and BRAILLE PATTERN
 * BLANK. They count as whitespace for the padding rules.
 */
private val MOSAIC_BLANK_CHARACTERS: Set<Int> = setOf(0x115F, 0x1160, 0x2800, 0x3164, 0xFFA0)

/**
 * Unicode's Default_Ignorable_Code_Point (the JDK has no property for it),
 * minus the blanks above: variation selectors, COMBINING GRAPHEME JOINER and
 * the like. Dropped before the padding and dot rules, so `<space><VS1><space>`
 * is still a run while an emoji's own selector (`❤️ list.txt`) is fine. The
 * browser host uses `\p{DI}` and SwiftUI `isDefaultIgnorableCodePoint`.
 */
private fun mosaicIsInvisible(point: Int): Boolean =
    point !in MOSAIC_BLANK_CHARACTERS && (
        point == 0x00AD || point == 0x034F || point == 0x061C ||
            point in 0x115F..0x1160 || point in 0x17B4..0x17B5 || point in 0x180B..0x180F ||
            point in 0x200B..0x200F || point in 0x202A..0x202E || point in 0x2060..0x206F ||
            point == 0x3164 || point in 0xFE00..0xFE0F || point == 0xFEFF || point == 0xFFA0 ||
            point in 0xFFF0..0xFFF8 || point in 0x1BCA0..0x1BCA3 || point in 0x1D173..0x1D17A ||
            point in 0xE0000..0xE0FFF
        )

/**
 * Extensions that run when the file is opened, on some platform: when an app
 * names no type (`accept` empty) a save may not end in one of these, so a
 * `files.save` cannot drop a launcher next to the person's documents. When the
 * app does name types, the name must already end in one of theirs.
 */
val MOSAIC_EXECUTABLE_EXTENSIONS: Set<String> = setOf(
    // macOS: Terminal scripts, Finder location files and installers open
    // with no prompt, or install.
    "command", "terminal", "tool", "webloc", "inetloc", "fileloc", "afploc", "ftploc",
    "mailloc", "newsloc", "atloc", "app", "pkg", "mpkg", "dmg", "mobileconfig", "scpt",
    "applescript", "workflow",
    // Windows: run, install, or leak credentials when merely browsed.
    "exe", "com", "bat", "cmd", "scr", "pif", "msi", "msp", "msc", "lnk", "url", "hta",
    "cpl", "chm", "inf", "vbs", "vbe", "js", "jse", "wsf", "wsh", "ws", "wsc", "sct",
    "ps1", "psm1", "reg", "jar", "jnlp", "gadget", "xll", "appref-ms", "application",
    "settingcontent-ms", "appx", "msix", "appinstaller", "diagcab", "scf",
    "library-ms", "searchconnector-ms", "iso", "img", "vhd", "vhdx",
    // Linux desktops.
    "desktop", "sh", "run", "appimage", "deb", "rpm", "flatpakref",
    // Documents that run code when opened: web pages and SVG (their script
    // runs from the local file), saved web archives and shortcuts, and Office
    // files that carry macros.
    "html", "htm", "xhtml", "xht", "shtml", "svg", "svgz", "mht", "mhtml", "website",
    "docm", "dotm", "xlsm", "xltm", "xlam", "pptm", "potm", "ppam", "ppsm", "sldm",
    "xlsb", "xla",
    // Scripts an installed interpreter runs on a double-click.
    "py", "pyw", "pyz", "pyzw", "pyc",
    // Shortcuts that fetch or connect: Excel web queries, SYLK, Remote Desktop.
    "iqy", "slk", "rdp",
)

/** True when [name] ends in an extension from [MOSAIC_EXECUTABLE_EXTENSIONS]. */
fun mosaicHasExecutableExtension(name: String): Boolean {
    val dot = name.lastIndexOf('.')
    if (dot < 0) return false
    val extension = name.substring(dot + 1)
    // A non-ASCII extension counts as one: a lookalike letter (Cyrillic `е`
    // in `ехе`) or a combining mark after `.exe` makes an extension no list
    // can name but a reader takes for an executable one.
    if (extension.any { it.code > 0x7F }) return true
    // Folded through upper case first: `ſ` (LONG S) lowercases to itself but
    // is `S` to a case-insensitive file system.
    return extension.uppercase().lowercase() in MOSAIC_EXECUTABLE_EXTENSIONS
}

/**
 * Route one effect (UI87 §7.2). Returns true when this library took it, false
 * when it belongs to the app's handler, and null when nobody should answer it
 * here (the host then fails an unanswered Await).
 */
fun mosaicRoutesToPlatform(kind: String, appKinds: Set<String>?): Boolean? = when {
    appKinds?.contains(kind) == true -> false
    kind in MOSAIC_STANDARD_EFFECT_KINDS -> true
    appKinds == null -> false
    else -> null
}

// ---- The asynchronous path (UI89 §3.8) -------------------------------------

/**
 * A failure whose message the app may see. Anything else a picker or a
 * document throws is reported with a fixed message instead: an exception's own
 * text can carry a local path, and a failure message is data the app sees.
 */
class MosaicFileFailure(message: String) : Exception(message)

/** A document the person chose to open. */
interface MosaicOpenedDocument {
    /** Its name, as the app is told it; never a path. */
    val name: String

    /** The provider's MIME type, or null to take it from the name. */
    val mimeType: String?

    /** Its bytes: at most [limit] of them, or null when it is longer. */
    fun read(limit: Long): ByteArray?
}

/** Where the person chose to save. */
interface MosaicSaveTarget {
    /** The name it is saved under, which a provider may have changed. */
    val name: String

    /** Write [bytes] there, replacing what was there; throws on failure. */
    fun write(bytes: ByteArray)
}

/**
 * The system's file pickers. Each call answers `done` once, with the person's
 * choice or null for a cancel -- before returning (a modal desktop dialog) or
 * later (a phone's picker). A picker that cannot be shown throws; a
 * [MosaicFileFailure]'s message reaches the app.
 *
 * `create` is given the whole checked request, bytes included: a picker that
 * exports a file it is handed (iOS) needs them before it is shown; one that
 * returns a place to write (the desktop, Android) leaves them to the target.
 */
interface MosaicDocumentPicker {
    fun open(accept: MosaicAccept, done: (MosaicOpenedDocument?) -> Unit)
    fun create(request: MosaicSaveRequest, done: (MosaicSaveTarget?) -> Unit)
}

/** A `files.save` request that met every rule of UI87 §3.1. */
class MosaicSaveRequest(val suggestedName: String, val bytes: ByteArray, val accept: MosaicAccept)

/**
 * Check a `files.save` request before any picker is shown, exactly as on
 * every host. Throws a [MosaicFileFailure] naming the rule it broke.
 */
fun mosaicCheckSaveRequest(payload: Any?): MosaicSaveRequest {
    val request = mosaicPayloadMap(payload)
    val suggestedName = request["suggestedName"] as? String ?: ""
    if (!mosaicIsPlainFileName(suggestedName)) {
        throw MosaicFileFailure("suggestedName must be a plain file name")
    }
    val encoded = request["bytes"] as? String ?: throw MosaicFileFailure("bytes must be base64 text")
    // Checked on the encoded length before decoding, so an oversized payload
    // is refused without allocating its decoded copy (4 base64 chars = 3 bytes).
    if (encoded.length.toLong() > (MOSAIC_MAX_SAVE_BYTES.toLong() / 3 + 1) * 4) {
        throw MosaicFileFailure("the file is larger than $MOSAIC_MAX_SAVE_BYTES bytes")
    }
    val bytes = try {
        Base64.getDecoder().decode(encoded)
    } catch (error: IllegalArgumentException) {
        throw MosaicFileFailure("bytes must be base64 text")
    }
    if (bytes.size > MOSAIC_MAX_SAVE_BYTES) {
        throw MosaicFileFailure("the file is larger than $MOSAIC_MAX_SAVE_BYTES bytes")
    }
    // When the app says what it is saving, the name must agree: a JSON export
    // cannot be offered as `notes.exe`.
    val accept = mosaicAcceptFor(request)
    if (accept.extensions.isNotEmpty() && accept.extensions.none { suggestedName.lowercase().endsWith(".$it") }) {
        throw MosaicFileFailure("suggestedName must end in an extension of an accepted type")
    }
    if (accept.extensions.isEmpty() && mosaicHasExecutableExtension(suggestedName)) {
        throw MosaicFileFailure("suggestedName must not end in an executable extension")
    }
    return MosaicSaveRequest(suggestedName, bytes, accept)
}

/** [answer], called at most once however often the result is. */
internal fun mosaicOnce(answer: (Map<String, Any?>) -> Unit): (Map<String, Any?>) -> Unit {
    val answered = AtomicBoolean(false)
    return { outcome -> if (answered.compareAndSet(false, true)) answer(outcome) }
}

/**
 * `files.open`, from request to [answer] -- called once, never with an
 * exception. The picker is asked; the chosen document is read on
 * [runInBackground], the 50 MiB limit enforced while reading.
 */
fun mosaicAnswerFilesOpen(
    payload: Any?,
    picker: MosaicDocumentPicker,
    runInBackground: (() -> Unit) -> Unit,
    answer: (Map<String, Any?>) -> Unit,
) {
    val once = mosaicOnce(answer)
    val picked = AtomicBoolean(false)
    try {
        picker.open(mosaicAcceptFor(mosaicPayloadMap(payload))) { document ->
            // A picker that answers twice is heard once.
            if (!picked.compareAndSet(false, true)) return@open
            if (document == null) {
                once(mosaicCancelled())
                return@open
            }
            try {
                runInBackground {
                    // Nothing escapes the background: a throw there (an
                    // OutOfMemoryError encoding a large file) would reach no
                    // caller and leave the effect awaited for good.
                    once(
                        try {
                            mosaicReadOpened(document)
                        } catch (error: Throwable) {
                            mosaicFailed("couldn't read the selected file")
                        }
                    )
                }
            } catch (error: Throwable) {
                once(mosaicFailed("couldn't read the selected file"))
            }
        }
    } catch (failure: MosaicFileFailure) {
        once(mosaicFailed(failure.message ?: "the file dialog failed"))
    } catch (error: Throwable) {
        once(mosaicFailed("the file dialog failed"))
    }
}

private fun mosaicReadOpened(document: MosaicOpenedDocument): Map<String, Any?> {
    val bytes = try {
        document.read(MOSAIC_MAX_OPEN_BYTES)
    } catch (failure: MosaicFileFailure) {
        return mosaicFailed(failure.message ?: "couldn't read the selected file")
    } catch (error: Throwable) {
        return mosaicFailed("couldn't read the selected file")
    } ?: return mosaicFailed("the selected file is larger than $MOSAIC_MAX_OPEN_BYTES bytes")
    return mosaicOk(
        mapOf(
            "name" to document.name,
            "mimeType" to (document.mimeType ?: mosaicMimeTypeForName(document.name)),
            "bytes" to Base64.getEncoder().encodeToString(bytes),
        )
    )
}

/**
 * `files.save`, from request to [answer] -- called once, never with an
 * exception. The request is checked first (a refusal shows no picker), the
 * picker is asked, and the bytes are written on [runInBackground].
 */
fun mosaicAnswerFilesSave(
    payload: Any?,
    picker: MosaicDocumentPicker,
    runInBackground: (() -> Unit) -> Unit,
    answer: (Map<String, Any?>) -> Unit,
) {
    val once = mosaicOnce(answer)
    val request = try {
        mosaicCheckSaveRequest(payload)
    } catch (failure: MosaicFileFailure) {
        once(mosaicFailed(failure.message ?: "couldn't save the file"))
        return
    }
    val picked = AtomicBoolean(false)
    try {
        picker.create(request) { target ->
            if (!picked.compareAndSet(false, true)) return@create
            if (target == null) {
                once(mosaicCancelled())
                return@create
            }
            try {
                runInBackground {
                    once(
                        try {
                            mosaicWriteTarget(target, request.bytes)
                        } catch (error: Throwable) {
                            mosaicFailed("couldn't save the file")
                        }
                    )
                }
            } catch (error: Throwable) {
                once(mosaicFailed("couldn't save the file"))
            }
        }
    } catch (failure: MosaicFileFailure) {
        once(mosaicFailed(failure.message ?: "the file dialog failed"))
    } catch (error: Throwable) {
        once(mosaicFailed("the file dialog failed"))
    }
}

private fun mosaicWriteTarget(target: MosaicSaveTarget, bytes: ByteArray): Map<String, Any?> =
    try {
        target.write(bytes)
        mosaicOk(mapOf("name" to target.name))
    } catch (failure: MosaicFileFailure) {
        mosaicFailed(failure.message ?: "couldn't save the file")
    } catch (error: Throwable) {
        mosaicFailed("couldn't save the file")
    }

/**
 * The handler this library installs: it routes each effect by kind (UI87 §7.2)
 * and answers the standard kinds itself, through [picker]. A named class, so
 * installing twice is recognisable -- the desktop `Main.kt` installs from
 * inside `application { }`, which can run again, and re-wrapping would stack
 * one router inside another.
 *
 * [runOnUi] is where a picker is shown. [runInBackground] is where a chosen
 * document is read or written: null (the desktop) reads and writes inline, on
 * the AWT thread, as it always has; otherwise (Android) the work runs there
 * and its outcome is handed back through [runOnUi] before the effect is
 * completed, so the host is only ever completed from the UI thread.
 */
class MosaicPlatformRouter(
    private val host: MosaicPlatformEffectHost,
    private val appHandler: ((Long, String, Any?, String) -> Unit)?,
    private val appKinds: Set<String>?,
    private val picker: MosaicDocumentPicker,
    private val runOnUi: (() -> Unit) -> Unit,
    private val runInBackground: ((() -> Unit) -> Unit)? = null,
) : (Long, String, Any?, String) -> Unit {
    // One file operation at a time (UI87 §3.1): a second request while a
    // picker is open is failed, not queued behind it.
    private val busy = AtomicBoolean(false)

    // The completion of the request in flight, while there is one.
    @Volatile
    private var pending: ((Map<String, Any?>) -> Unit)? = null

    override fun invoke(id: Long, kind: String, payload: Any?, delivery: String) {
        when (mosaicRoutesToPlatform(kind, appKinds)) {
            false -> appHandler?.invoke(id, kind, payload, delivery)
            null -> Unit
            true -> answerStandard(id, kind, payload, delivery)
        }
    }

    private fun answerStandard(id: Long, kind: String, payload: Any?, delivery: String) {
        // Only an Await has someone waiting for the answer.
        if (delivery.lowercase() != "await") return
        if (!busy.compareAndSet(false, true)) {
            host.completeEffect(id, mosaicFailed("another file operation is in progress"))
            return
        }
        // Ownership first. False means the runtime is not waiting on this id,
        // and the right move is to open no picker at all.
        if (!host.deferEffect(id)) {
            busy.set(false)
            return
        }
        lateinit var complete: (Map<String, Any?>) -> Unit
        complete = mosaicOnce { outcome ->
            if (pending === complete) pending = null
            busy.set(false)
            try {
                host.completeEffect(id, outcome)
            } catch (error: Throwable) {
                // The answer itself could not be delivered (a large file's
                // bytes exhausted memory on the way in). A deferred effect
                // that is never answered is awaited for good, so answer
                // again with something small; if the host refuses that too,
                // it reports it through its own warning channel.
                try {
                    host.completeEffect(id, mosaicFailed("couldn't deliver the file"))
                } catch (ignored: Throwable) {
                }
            }
        }
        pending = complete
        val background = runInBackground
        val work: (() -> Unit) -> Unit = background ?: { it() }
        val answer: (Map<String, Any?>) -> Unit = if (background == null) {
            complete
        } else {
            { outcome ->
                try {
                    runOnUi { complete(outcome) }
                } catch (error: Throwable) {
                    complete(outcome)
                }
            }
        }
        try {
            runOnUi {
                if (kind == "files.open") {
                    mosaicAnswerFilesOpen(payload, picker, work, answer)
                } else {
                    mosaicAnswerFilesSave(payload, picker, work, answer)
                }
            }
        } catch (error: Throwable) {
            complete(mosaicFailed("the file dialog failed"))
        }
    }

    /**
     * Fail the request a picker is still open for, when nothing can answer it
     * any more (on Android, the activity that registered the picker is gone),
     * so the runtime is not left awaiting it. A later answer from the picker
     * is ignored. Returns false when no request was waiting.
     */
    fun failPending(message: String): Boolean {
        val waiting = pending ?: return false
        waiting(mosaicFailed(message))
        return true
    }
}
